{
  "name": "Văn Sĩ - Nghe & Ngẫm Story Studio",
  "description": "Một ứng dụng chuyên dụng dành cho nhà văn để sáng tác truyện dài thể loại Đời thường và Tâm lý xã hội, tối ưu cho audio 90 phút.",
  "requestFramePermissions": ["microphone"]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Character {
  id: string;
  name: string;
  role: string;
  personality: string;
  internalConflict: string;
}

export interface Chapter {
  id: string;
  title: string;
  content: string;
  summary: string;
  emotionalTone: string;
}

export interface StoryProject {
  id: string;
  title: string;
  premise: string;
  setting: string;
  characters: Character[];
  outline: string[];
  chapters: Chapter[];
  createdAt: number;
}

export enum AppTab {
  DASHBOARD = 'DASHBOARD',
  EDITOR = 'EDITOR',
  CHARACTERS = 'CHARACTERS',
  OUTLINE = 'OUTLINE'
}

import { GoogleGenAI, Type } from "@google/genai";
import { StoryProject, Character, Chapter } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = `Bạn là một nhà văn chuyên nghiệp chuyên viết truyện dài thể loại Đời thường (Slice of Life) và Tâm lý xã hội tại Việt Nam cho kênh YouTube 'Nghe & Ngẫm'. 
Giọng văn của bạn cần:
1. Sâu lắng, giàu cảm xúc, sử dụng nhiều từ ngữ gợi hình gợi cảm.
2. Tập trung khai thác chiều sâu nội tâm, những trăn trở thầm kín của nhân vật.
3. Bối cảnh Việt Nam gần gũi (thành thị sầm uất hoặc thôn quê bình dị).
4. Nhịp độ chậm rãi, phù hợp để đọc audio (khoảng 150 từ/phút).
5. Tránh các tình tiết giật gân rẻ tiền, tập trung vào giá trị nhân văn và sự chữa lành.`;

export const generateStoryIdea = async (prompt: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Hãy gợi ý 3 ý tưởng truyện dài (Slice of Life/Tâm lý xã hội) dựa trên yêu cầu: ${prompt}. Mỗi ý tưởng bao gồm: Tiêu đề, Tóm tắt cốt truyện, và Thông điệp chính.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
    },
  });
  return response.text;
};

export const generateOutline = async (title: string, premise: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Lập dàn ý chi tiết cho truyện "${title}" với cốt truyện: ${premise}. Chia thành khoảng 10-12 chương để đảm bảo tổng độ dài khi viết xong đạt 15.000 từ (phục vụ audio 90 phút). Mỗi chương nêu rõ sự kiện chính và diễn biến tâm lý.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
    },
  });
  return response.text;
};

export const writeChapterContent = async (
  project: StoryProject,
  chapterIndex: number,
  additionalContext: string = ""
) => {
  const chapter = project.chapters[chapterIndex];
  const prevChapter = chapterIndex > 0 ? project.chapters[chapterIndex - 1] : null;

  const prompt = `
    Viết nội dung chi tiết cho Chương ${chapterIndex + 1}: "${chapter.title}" của truyện "${project.title}".
    Tóm tắt chương này: ${chapter.summary}.
    Bối cảnh: ${project.setting}.
    Nhân vật chính: ${project.characters.map(c => c.name).join(", ")}.
    ${prevChapter ? `Tiếp nối diễn biến: ${prevChapter.summary}` : ""}
    Yêu cầu: Viết khoảng 1500-2000 từ. Tập trung vào miêu tả tâm lý, đối thoại tự nhiên, giàu chất thơ. 
    ${additionalContext ? `Lưu ý thêm: ${additionalContext}` : ""}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
      thinkingConfig: { thinkingBudget: 4000 }
    },
  });
  return response.text;
};

import React, { useState, useEffect, useCallback } from 'react';
import { StoryProject, AppTab, Character, Chapter } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import StoryEditor from './components/StoryEditor';
import CharacterManager from './components/CharacterManager';
import OutlineManager from './components/OutlineManager';

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('van_si_projects');
    if (saved) {
      try {
        setProjects(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse projects", e);
      }
    }
  }, []);

  // Save to localStorage when projects change
  useEffect(() => {
    localStorage.setItem('van_si_projects', JSON.stringify(projects));
  }, [projects]);

  const currentProject = projects.find(p => p.id === currentProjectId) || null;

  const createNewProject = (title: string, premise: string) => {
    const newProject: StoryProject = {
      id: Date.now().toString(),
      title,
      premise,
      setting: 'Việt Nam hiện đại',
      characters: [],
      outline: [],
      chapters: [],
      createdAt: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
    setActiveTab(AppTab.OUTLINE);
  };

  const updateProject = useCallback((updated: StoryProject) => {
    setProjects(prev => prev.map(p => p.id === updated.id ? updated : p));
  }, []);

  const deleteProject = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa tác phẩm này?")) {
      setProjects(prev => prev.filter(p => p.id !== id));
      if (currentProjectId === id) {
        setCurrentProjectId(null);
        setActiveTab(AppTab.DASHBOARD);
      }
    }
  };

  return (
    <div className="flex h-screen overflow-hidden text-slate-800">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        onSelectProject={(id) => {
          setCurrentProjectId(id);
          setActiveTab(AppTab.EDITOR);
        }}
        onNewProject={() => {
          setCurrentProjectId(null);
          setActiveTab(AppTab.DASHBOARD);
        }}
        activeTab={activeTab}
        setActiveTab={setActiveTab}
      />

      <main className="flex-1 flex flex-col bg-[#fdfaf7] relative overflow-hidden">
        {activeTab === AppTab.DASHBOARD && (
          <Dashboard 
            onCreate={createNewProject} 
            projects={projects}
            onSelectProject={(id) => {
              setCurrentProjectId(id);
              setActiveTab(AppTab.EDITOR);
            }}
            onDelete={deleteProject}
          />
        )}

        {currentProject && activeTab === AppTab.EDITOR && (
          <StoryEditor 
            project={currentProject} 
            onUpdate={updateProject} 
          />
        )}

        {currentProject && activeTab === AppTab.CHARACTERS && (
          <CharacterManager 
            project={currentProject} 
            onUpdate={updateProject} 
          />
        )}

        {currentProject && activeTab === AppTab.OUTLINE && (
          <OutlineManager 
            project={currentProject} 
            onUpdate={updateProject} 
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
