export default Sidebar;

import React, { useState } from 'react';
import { StoryProject } from '../types';
import { PlusIcon, TrashIcon } from './Icons';
import { generateStoryIdea } from '../services/geminiService';

interface DashboardProps {
  projects: StoryProject[];
  onCreate: (title: string, premise: string) => void;
  onSelectProject: (id: string) => void;
  onDelete: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ projects, onCreate, onSelectProject, onDelete }) => {
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [title, setTitle] = useState('');
  const [premise, setPremise] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<string | null>(null);

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !premise) return;
    onCreate(title, premise);
    setShowCreateModal(false);
    setTitle('');
    setPremise('');
  };

  const handleAiBrainstorm = async () => {
    if (!premise) return;
    setIsGenerating(true);
    try {
      const suggestions = await generateStoryIdea(premise);
      setAiSuggestions(suggestions);
    } catch (error) {
      alert("Không thể kết nối với trí tuệ nhân tạo.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="p-10 max-w-6xl mx-auto w-full h-full overflow-y-auto">
      <header className="mb-12">
        <h2 className="text-4xl font-serif font-bold text-stone-800 mb-2">Chào mừng nhà văn,</h2>
        <p className="text-stone-500 italic">"Viết là một cách để lắng nghe những tiếng vang nhỏ nhất của tâm hồn."</p>
      </header>

      <section className="mb-12">
        <div className="flex justify-between items-end mb-6">
          <h3 className="text-xl font-semibold text-stone-700">Tác phẩm gần đây</h3>
          <button 
            onClick={() => setShowCreateModal(true)}
            className="flex items-center gap-2 text-amber-700 hover:text-amber-800 font-medium border-b-2 border-amber-200 pb-1"
          >
            <PlusIcon className="w-5 h-5" />
            Bắt đầu dự án mới
          </button>
        </div>

        {projects.length === 0 ? (
          <div className="bg-white border-2 border-dashed border-stone-200 rounded-3xl p-20 text-center">
            <p className="text-stone-400 mb-4">Bạn chưa có tác phẩm nào. Hãy bắt đầu kể một câu chuyện ngay!</p>
            <button 
              onClick={() => setShowCreateModal(true)}
              className="bg-amber-800 text-white px-8 py-3 rounded-full hover:bg-amber-900 transition-colors shadow-lg"
            >
              Tạo dự án đầu tiên
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {projects.map(p => (
              <div 
                key={p.id} 
                className="group bg-white p-6 rounded-2xl shadow-sm border border-stone-100 hover:shadow-xl transition-all cursor-pointer relative"
              >
                <div onClick={() => onSelectProject(p.id)}>
                  <h4 className="text-lg font-bold text-stone-800 mb-2 font-serif group-hover:text-amber-800 transition-colors">{p.title}</h4>
                  <p className="text-sm text-stone-500 line-clamp-3 mb-4">{p.premise}</p>
                  <div className="flex justify-between items-center text-[10px] text-stone-400 font-bold uppercase tracking-widest">
                    <span>{p.chapters.length} chương</span>
                    <span>{new Date(p.createdAt).toLocaleDateString('vi-VN')}</span>
                  </div>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(p.id); }}
                  className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 p-2 text-stone-300 hover:text-red-500 transition-all"
                >
                  <TrashIcon className="w-5 h-5" />
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      {showCreateModal && (
        <div className="fixed inset-0 bg-stone-900/40 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-[#fdfaf7] rounded-3xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-8 overflow-y-auto">
              <h3 className="text-2xl font-serif font-bold text-stone-800 mb-6">Khởi tạo tác phẩm</h3>
              <form onSubmit={handleCreate} className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-stone-600 uppercase mb-2">Tiêu đề truyện</label>
                  <input 
                    type="text" 
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    className="w-full bg-white border border-stone-200 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-amber-200 transition-all"
                    placeholder="Nhập tên câu chuyện..."
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-stone-600 uppercase mb-2">Cốt truyện sơ bộ (Premise)</label>
                  <textarea 
                    value={premise}
                    onChange={(e) => setPremise(e.target.value)}
                    className="w-full bg-white border border-stone-200 rounded-xl px-4 py-3 h-32 focus:outline-none focus:ring-2 focus:ring-amber-200 transition-all resize-none"
                    placeholder="Mô tả ngắn gọn về câu chuyện hoặc ý tưởng của bạn..."
                    required
                  />
                </div>

                <div className="flex gap-4">
                  <button 
                    type="button"
                    onClick={handleAiBrainstorm}
                    disabled={isGenerating || !premise}
                    className="flex-1 border-2 border-amber-800 text-amber-800 py-3 rounded-xl hover:bg-amber-50 disabled:opacity-50 transition-colors font-bold"
                  >
                    {isGenerating ? 'Đang suy nghĩ...' : '🤖 Nhờ AI gợi ý ý tưởng'}
                  </button>
                  <button 
                    type="submit"
                    className="flex-1 bg-amber-800 text-white py-3 rounded-xl hover:bg-amber-900 transition-colors font-bold shadow-lg"
                  >
                    Bắt đầu viết
                  </button>
                </div>
              </form>

              {aiSuggestions && (
                <div className="mt-8 p-6 bg-white border border-stone-100 rounded-2xl">
                  <h4 className="font-bold text-stone-800 mb-3 text-sm uppercase tracking-wider">💡 Gợi ý từ Gemini:</h4>
                  <div className="prose prose-sm text-stone-600 max-h-60 overflow-y-auto whitespace-pre-wrap font-serif italic leading-relaxed">
                    {aiSuggestions}
                  </div>
                </div>
              )}
            </div>
            <div className="p-4 bg-stone-50 text-right">
              <button 
                onClick={() => setShowCreateModal(false)}
                className="text-stone-400 hover:text-stone-600 font-medium text-sm"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { StoryProject, Chapter } from '../types';
import { writeChapterContent } from '../services/geminiService';
import { SparklesIcon, SaveIcon, ChevronLeftIcon, ChevronRightIcon } from './Icons';

interface StoryEditorProps {
  project: StoryProject;
  onUpdate: (updated: StoryProject) => void;
}

const StoryEditor: React.FC<StoryEditorProps> = ({ project, onUpdate }) => {
  const [activeChapterIndex, setActiveChapterIndex] = useState(0);
  const [isWriting, setIsWriting] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const currentChapter = project.chapters[activeChapterIndex];

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [activeChapterIndex, currentChapter?.content]);

  if (project.chapters.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-10 bg-[#fdfaf7]">
        <div className="max-w-md text-center">
          <h2 className="text-2xl font-serif font-bold text-stone-800 mb-4">Chưa có chương nào</h2>
          <p className="text-stone-500 mb-8">Hãy sang phần "Dàn ý & Chương" để lập kế hoạch cho câu chuyện của bạn trước khi bắt đầu viết.</p>
        </div>
      </div>
    );
  }

  const handleContentChange = (content: string) => {
    const updatedChapters = [...project.chapters];
    updatedChapters[activeChapterIndex] = { ...currentChapter, content };
    onUpdate({ ...project, chapters: updatedChapters });
  };

  const generateAIContent = async () => {
    setIsWriting(true);
    setStatusMessage('Văn sĩ AI đang chấp bút những dòng đầu tiên...');
    try {
      const result = await writeChapterContent(project, activeChapterIndex);
      handleContentChange(result);
      setStatusMessage('Đã hoàn thành phân đoạn này.');
      setTimeout(() => setStatusMessage(''), 3000);
    } catch (error) {
      console.error(error);
      alert("Không thể tạo nội dung. Kiểm tra API Key của bạn.");
    } finally {
      setIsWriting(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-[#fdfaf7] relative">
      {/* Editor Header */}
      <header className="px-8 py-4 border-b border-stone-200 flex justify-between items-center bg-white/80 backdrop-blur-md sticky top-0 z-10">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            <button 
              disabled={activeChapterIndex === 0}
              onClick={() => setActiveChapterIndex(prev => prev - 1)}
              className="p-2 hover:bg-stone-100 rounded-full disabled:opacity-30"
            >
              <ChevronLeftIcon className="w-5 h-5" />
            </button>
            <span className="font-serif font-bold text-stone-800 text-lg">
              Chương {activeChapterIndex + 1}: {currentChapter.title}
            </span>
            <button 
              disabled={activeChapterIndex === project.chapters.length - 1}
              onClick={() => setActiveChapterIndex(prev => prev + 1)}
              className="p-2 hover:bg-stone-100 rounded-full disabled:opacity-30"
            >
              <ChevronRightIcon className="w-5 h-5" />
            </button>
          </div>
          <div className="text-xs text-stone-400 font-medium uppercase tracking-widest border-l border-stone-200 pl-6">
            Độ dài: {currentChapter.content.split(/\s+/).filter(x => x).length} từ
          </div>
        </div>

        <div className="flex items-center gap-3">
          <span className="text-xs text-amber-600 font-medium animate-pulse">{statusMessage}</span>
          <button 
            onClick={generateAIContent}
            disabled={isWriting}
            className="flex items-center gap-2 bg-amber-50 text-amber-800 px-4 py-2 rounded-full border border-amber-200 hover:bg-amber-100 transition-all font-bold text-sm shadow-sm"
          >
            <SparklesIcon className="w-4 h-4" />
            {isWriting ? 'Đang viết...' : 'AI Chấp bút'}
          </button>
          <button className="flex items-center gap-2 bg-stone-800 text-white px-5 py-2 rounded-full hover:bg-stone-900 transition-all font-bold text-sm shadow-md">
