                  <div>
                    <input 
                      value={char.name}
                      onChange={(e) => handleEdit(char.id, { name: e.target.value })}
                      className="text-lg font-serif font-bold text-stone-800 bg-transparent border-none focus:outline-none focus:ring-1 focus:ring-amber-200 rounded px-1"
                    />
                    <input 
                      value={char.role}
                      onChange={(e) => handleEdit(char.id, { role: e.target.value })}
