import { GoogleGenAI, Type } from "@google/genai";
import { StoryProject, Character, Chapter } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = `Bạn là một nhà văn chuyên viết truyện dài thể loại Đời thường (Slice of Life) và Tâm lý xã hội tại Việt Nam cho kênh YouTube 'Nghe & Ngẫm'.

QUY TẮC CỐT LÕI:
1. NGÔN NGỮ: Sử dụng tiếng Việt thuần túy, giàu hình ảnh, chau chuốt nhưng gãy gọn. Linh hoạt dùng từ láy và thành ngữ phù hợp bối cảnh Việt Nam. Tuyệt đối không dùng văn phong báo chí hay từ lóng hiện đại (trừ khi đối thoại nhân vật trẻ).
2. TÂM LÝ (SHOW, DON'T TELL): Không chỉ kể sự việc, hãy vẽ ra tâm trạng thông qua cử chỉ, ánh mắt, hơi thở và không gian xung quanh. Tập trung vào những rung động nhỏ nhất của tâm hồn.
3. NHỊP ĐIỆU: Chậm rãi, từ tốn, tạo những khoảng lặng để thính giả audio có thời gian ngấm và suy ngẫm.
4. TÍNH CHÂN THỰC: Bối cảnh gia đình, xóm làng, công sở Việt Nam phải logic. Tránh kịch tính hóa (drama) quá đà kiểu rẻ tiền.
5. NHÂN VĂN: Hướng tới sự đồng cảm, chữa lành và những giá trị đạo đức cao đẹp của người Việt.`;

export const generateStoryIdea = async (prompt: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Hãy gợi ý 3 ý tưởng truyện dài sâu sắc dựa trên yêu cầu: ${prompt}. Mỗi ý tưởng gồm: Tiêu đề, Tóm tắt cốt truyện (Focus vào tâm lý), và Thông điệp nhân văn.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
    },
  });
  return response.text;
};

export const generateOutline = async (title: string, premise: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Lập dàn ý chi tiết cho truyện "${title}" với cốt truyện: ${premise}. Chia thành 10-12 chương. Mỗi chương cần nêu rõ: Biến cố bên ngoài và Sự chuyển biến nội tâm nhân vật chính. Mục tiêu tổng 15.000 từ.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
    },
  });
  return response.text;
};

export const writeChapterContent = async (
  project: StoryProject,
  chapterIndex: number,
  additionalContext: string = ""
) => {
  const chapter = project.chapters[chapterIndex];
  const charContext = project.characters.map(c => 
    `- ${c.name}: ${c.role}. Tính cách: ${c.personality}. Nỗi đau: ${c.pastPain}. Khao khát: ${c.currentDesire}.`
  ).join("\n");

  const prompt = `
    VIẾT CHI TIẾT CHƯƠNG ${chapterIndex + 1}: "${chapter.title}"
    Tóm tắt: ${chapter.summary}
    Bối cảnh: ${project.setting}
    Hồ sơ tâm lý nhân vật:
    ${charContext}

    YÊU CẦU BÚT PHÁP: 
    - Viết khoảng 1500-2000 từ.
    - Áp dụng triệt để "Show, Don't Tell". Miêu tả sự vật để nói về sự người.
    - Đối thoại tự nhiên, mang hơi thở đời sống Việt.
    - Tập trung vào mâu thuẫn giữa nỗi đau quá khứ và khao khát hiện tại.
    ${additionalContext ? `Lưu ý đặc biệt: ${additionalContext}` : ""}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
      thinkingConfig: { thinkingBudget: 6000 }
    },
  });
  return response.text;
};

export const critiqueWriting = async (content: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Với tư cách là một biên tập viên văn học khó tính, hãy nhận xét đoạn văn sau về:
    1. Độ sâu sắc của nội tâm (Đã Show thay vì Tell chưa?)
    2. Nhịp điệu và từ ngữ (Có giàu hình ảnh và chất thơ không?)
    3. Tính logic đời sống Việt Nam.
    Đoạn văn: ${content}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.5,
    },
  });
  return response.text;
};

export const rewriteChapter = async (
  project: StoryProject,
  chapterIndex: number,
  currentContent: string,
  critique: string
) => {
  const chapter = project.chapters[chapterIndex];
  const charContext = project.characters.map(c => 
    `- ${c.name}: ${c.role}. Tính cách: ${c.personality}. Nỗi đau: ${c.pastPain}. Khao khát: ${c.currentDesire}.`
  ).join("\n");

  const prompt = `
    Bạn là một nhà văn đang chỉnh sửa bản thảo dựa trên góp ý của biên tập viên.

    BỐI CẢNH & NHÂN VẬT:
    ${charContext}

    NỘI DUNG GỐC (CHƯƠNG ${chapterIndex + 1}: ${chapter.title}):
    ${currentContent}

    GÓP Ý CỦA BIÊN TẬP VIÊN:
    ${critique}

    NHIỆM VỤ:
    Hãy viết lại chương này, áp dụng triệt để các góp ý trên để nâng cao chất lượng văn học. 
    Giữ nguyên cốt truyện gốc, chỉ thay đổi cách diễn đạt, miêu tả tâm lý và nhịp điệu theo hướng dẫn.
    Đảm bảo văn phong sâu lắng, giàu hình ảnh (Show, Don't Tell) theo đúng phong cách của kênh 'Nghe & Ngẫm'.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
      thinkingConfig: { thinkingBudget: 4000 }
    },
  });
  return response.text;
};

import React, { useState, useEffect, useRef } from 'react';
import { StoryProject, Chapter } from '../types';
import { writeChapterContent, critiqueWriting, rewriteChapter } from '../services/geminiService';
import { SparklesIcon, SaveIcon, ChevronLeftIcon, ChevronRightIcon, ChatBubbleLeftEllipsisIcon } from './Icons';

interface StoryEditorProps {
  project: StoryProject;
  onUpdate: (updated: StoryProject) => void;
}

const StoryEditor: React.FC<StoryEditorProps> = ({ project, onUpdate }) => {
  const [activeChapterIndex, setActiveChapterIndex] = useState(0);
  const [isWriting, setIsWriting] = useState(false);
  const [isCritiquing, setIsCritiquing] = useState(false);
  const [critique, setCritique] = useState<string | null>(null);
  const [statusMessage, setStatusMessage] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const currentChapter = project.chapters[activeChapterIndex];

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [activeChapterIndex, currentChapter?.content]);

  if (project.chapters.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-10 bg-[#fdfaf7]">
        <h2 className="text-2xl font-serif font-bold text-stone-800 mb-4">Bản thảo trống</h2>
        <p className="text-stone-500 mb-8">Hãy phác thảo dàn ý trước khi bắt đầu viết những dòng cảm xúc đầu tiên.</p>
      </div>
    );
  }

  const handleContentChange = (content: string) => {
    const updatedChapters = [...project.chapters];
    updatedChapters[activeChapterIndex] = { ...currentChapter, content };
    onUpdate({ ...project, chapters: updatedChapters });
  };

  const generateAIContent = async () => {
    setIsWriting(true);
    setStatusMessage('Văn sĩ AI đang tìm kiếm cảm hứng...');
    try {
      const result = await writeChapterContent(project, activeChapterIndex);
      handleContentChange(result);
      setStatusMessage('Bản thảo đã sẵn sàng để trau chuốt.');
      setTimeout(() => setStatusMessage(''), 4000);
    } catch (error) {
      alert("Kết nối bị gián đoạn. Hãy thử lại sau.");
    } finally {
      setIsWriting(false);
    }
  };

  const handleCritique = async () => {
    if (!currentChapter.content) return;
    setIsCritiquing(true);
    try {
      const result = await critiqueWriting(currentChapter.content);
      setCritique(result);
    } catch (error) {
      alert("Biên tập viên đang bận.");
    } finally {
      setIsCritiquing(false);
    }
  };

  const handleApplyCritique = async () => {
    if (!currentChapter.content || !critique) return;
    setIsWriting(true);
    setStatusMessage('Văn sĩ AI đang gọt giũa lại câu chữ dựa trên góp ý...');
    try {
      const revisedContent = await rewriteChapter(project, activeChapterIndex, currentChapter.content, critique);
      handleContentChange(revisedContent);
      setStatusMessage('Đã hoàn tất chỉnh sửa.');
      setCritique(null);
      setTimeout(() => setStatusMessage(''), 4000);
    } catch (error) {
      console.error(error);
      alert("Không thể thực hiện sửa đổi lúc này.");
    } finally {
      setIsWriting(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-[#fdfaf7] relative overflow-hidden">
      <header className="px-10 py-5 border-b border-stone-200 flex justify-between items-center bg-white/60 backdrop-blur-xl sticky top-0 z-20">
        <div className="flex items-center gap-8">
          <div className="flex items-center gap-3">
            <button 
              disabled={activeChapterIndex === 0}
              onClick={() => setActiveChapterIndex(prev => prev - 1)}
              className="p-2 hover:bg-stone-100 rounded-full disabled:opacity-20 transition-colors"
            >
              <ChevronLeftIcon className="w-5 h-5" />
            </button>
            <div className="text-center min-w-[150px]">
              <p className="text-[10px] text-stone-400 font-bold uppercase tracking-widest mb-0.5">Chương {activeChapterIndex + 1}</p>
              <h3 className="font-serif font-bold text-stone-800 text-xl truncate max-w-[200px]">{currentChapter.title}</h3>
            </div>
            <button 
              disabled={activeChapterIndex === project.chapters.length - 1}
              onClick={() => setActiveChapterIndex(prev => prev + 1)}
              className="p-2 hover:bg-stone-100 rounded-full disabled:opacity-20 transition-colors"
            >
              <ChevronRightIcon className="w-5 h-5" />
            </button>
          </div>
          <div className="h-8 w-px bg-stone-200 mx-2"></div>
          <div className="text-[10px] text-stone-400 font-bold uppercase tracking-widest">
            {currentChapter.content.split(/\s+/).filter(x => x).length} chữ
          </div>
        </div>

        <div className="flex items-center gap-4">
          <span className="text-xs text-amber-600 font-serif italic">{statusMessage}</span>
          <button 
            onClick={handleCritique}
            disabled={isCritiquing || !currentChapter.content}
            className="flex items-center gap-2 px-5 py-2.5 rounded-full border border-stone-200 bg-white hover:bg-stone-50 transition-all font-bold text-xs text-stone-600 shadow-sm"
          >
            <ChatBubbleLeftEllipsisIcon className="w-4 h-4" />
            Phê bình
          </button>
          <button 
            onClick={generateAIContent}
            disabled={isWriting}
            className="flex items-center gap-2 bg-amber-900 text-white px-6 py-2.5 rounded-full hover:bg-stone-900 transition-all font-bold text-xs shadow-lg"
          >
            <SparklesIcon className="w-4 h-4 text-amber-300" />
            {isWriting ? 'Đang chấp bút...' : 'AI Chấp bút'}
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 overflow-y-auto pt-16 pb-32 px-10 md:px-24">
          <div className="max-w-4xl mx-auto">
            <textarea 
              ref={textareaRef}
              value={currentChapter.content}
              onChange={(e) => handleContentChange(e.target.value)}
              className="w-full text-xl leading-[2.2] text-stone-700 bg-transparent resize-none focus:outline-none font-serif placeholder:italic placeholder:text-stone-300"
              placeholder="Bắt đầu gieo những hạt mầm cảm xúc đầu tiên..."
              style={{ overflow: 'hidden' }}
            />
          </div>
        </div>

        {/* Floating Critique Panel */}
        {critique && (
          <div className="w-96 border-l border-stone-200 bg-white/80 backdrop-blur-md p-8 overflow-y-auto animate-in slide-in-from-right duration-500 flex flex-col">
            <div className="flex justify-between items-center mb-6">
              <h4 className="font-serif font-bold text-stone-800 text-lg">Góc nhìn biên tập</h4>
              <button onClick={() => setCritique(null)} className="text-stone-400 hover:text-stone-600">×</button>
            </div>
            <div className="prose prose-sm prose-stone italic text-stone-600 leading-relaxed whitespace-pre-wrap flex-1 mb-6">
              {critique}
            </div>

            <button
                onClick={handleApplyCritique}
                disabled={isWriting}
                className="w-full py-3 bg-amber-800 hover:bg-amber-900 text-white rounded-xl font-bold text-sm shadow-lg transition-all flex items-center justify-center gap-2 disabled:opacity-50"
            >
                <SparklesIcon className="w-4 h-4" />
                Áp dụng sửa đổi
            </button>
          </div>
        )}
      </div>

      {isWriting && (
        <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px] z-50 flex items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-stone-100 flex flex-col items-center max-w-sm text-center">
            <div className="w-12 h-12 border-4 border-amber-900/20 border-t-amber-900 rounded-full animate-spin mb-6"></div>
            <p className="font-serif italic text-stone-600">
                {statusMessage || "Văn chương là chuyện tâm hồn, hãy để văn sĩ AI lắng nghe nhịp đập của nhân vật..."}
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

