import { GoogleGenAI, Type } from "@google/genai";
import { StoryProject, Character, Chapter } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = `Bạn là một nhà văn chuyên viết truyện dài thể loại Đời thường (Slice of Life) và Tâm lý xã hội tại Việt Nam cho kênh YouTube 'Nghe & Ngẫm'.

QUY TẮC CỐT LÕI:
1. NGÔN NGỮ: Sử dụng tiếng Việt thuần túy, giàu hình ảnh, chau chuốt nhưng gãy gọn. Linh hoạt dùng từ láy và thành ngữ phù hợp bối cảnh Việt Nam. Tuyệt đối không dùng văn phong báo chí hay từ lóng hiện đại (trừ khi đối thoại nhân vật trẻ).
2. TÂM LÝ (SHOW, DON'T TELL): Không chỉ kể sự việc, hãy vẽ ra tâm trạng thông qua cử chỉ, ánh mắt, hơi thở và không gian xung quanh. Tập trung vào những rung động nhỏ nhất của tâm hồn.
3. NHỊP ĐIỆU: Chậm rãi, từ tốn, tạo những khoảng lặng để thính giả audio có thời gian ngấm và suy ngẫm.
4. TÍNH CHÂN THỰC: Bối cảnh gia đình, xóm làng, công sở Việt Nam phải logic. Tránh kịch tính hóa (drama) quá đà kiểu rẻ tiền.
5. NHÂN VĂN: Hướng tới sự đồng cảm, chữa lành và những giá trị đạo đức cao đẹp của người Việt.`;

export const generateStoryIdea = async (prompt: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Hãy gợi ý 3 ý tưởng truyện dài sâu sắc dựa trên yêu cầu: ${prompt}. Mỗi ý tưởng gồm: Tiêu đề, Tóm tắt cốt truyện (Focus vào tâm lý), và Thông điệp nhân văn.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
    },
  });
  return response.text;
};

export const generateOutline = async (title: string, premise: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Lập dàn ý chi tiết cho truyện "${title}" với cốt truyện: ${premise}. Chia thành 10-12 chương. Mỗi chương cần nêu rõ: Biến cố bên ngoài và Sự chuyển biến nội tâm nhân vật chính. Mục tiêu tổng 15.000 từ.`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
    },
  });
  return response.text;
};

export const generateNextChapterOutline = async (project: StoryProject) => {
  const existingChaptersContext = project.chapters
    .map((c, i) => `Chương ${i + 1}: ${c.title}\nTóm tắt: ${c.summary}\n`)
    .join('\n');

  const prompt = `
    Dựa trên tác phẩm:
    Tên truyện: ${project.title}
    Cốt truyện: ${project.premise}

    CÁC CHƯƠNG ĐÃ CÓ:
    ${existingChaptersContext}

    NHIỆM VỤ:
    Hãy sáng tạo nội dung cho CHƯƠNG ${project.chapters.length + 1} tiếp nối mạch cảm xúc trên.
    Trả về kết quả chính xác theo định dạng sau (không thêm lời dẫn):

    TIÊU ĐỀ: [Tên chương đầy chất thơ]
    TÓM TẮT: [Mô tả chi tiết diễn biến và tâm lý nhân vật]
    SẮC THÁI: [Chọn 1 trong: U sầu, Bình thản, Chữa lành, Hoài niệm, Kịch tính ngầm]
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
    },
  });
  return response.text;
};

export const writeChapterContent = async (
  project: StoryProject,
  chapterIndex: number,
  additionalContext: string = ""
) => {
  const chapter = project.chapters[chapterIndex];
  const charContext = project.characters.map(c => 
    `- ${c.name}: ${c.role}. Tính cách: ${c.personality}. Nỗi đau: ${c.pastPain}. Khao khát: ${c.currentDesire}.`
  ).join("\n");

  const prompt = `
    VIẾT CHI TIẾT CHƯƠNG ${chapterIndex + 1}: "${chapter.title}"
    Tóm tắt: ${chapter.summary}
    Bối cảnh: ${project.setting}
    Hồ sơ tâm lý nhân vật:
    ${charContext}

    YÊU CẦU BÚT PHÁP: 
    - Viết khoảng 1500-2000 từ.
    - Áp dụng triệt để "Show, Don't Tell". Miêu tả sự vật để nói về sự người.
    - Đối thoại tự nhiên, mang hơi thở đời sống Việt.
    - Tập trung vào mâu thuẫn giữa nỗi đau quá khứ và khao khát hiện tại.
    ${additionalContext ? `Lưu ý đặc biệt: ${additionalContext}` : ""}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.8,
      thinkingConfig: { thinkingBudget: 6000 }
    },
  });
  return response.text;
};

export const critiqueWriting = async (content: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Với tư cách là một biên tập viên văn học khó tính, hãy nhận xét đoạn văn sau về:
    1. Độ sâu sắc của nội tâm (Đã Show thay vì Tell chưa?)
    2. Nhịp điệu và từ ngữ (Có giàu hình ảnh và chất thơ không?)
    3. Tính logic đời sống Việt Nam.
    Đoạn văn: ${content}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.5,
    },
  });
  return response.text;
};

export const rewriteChapter = async (
  project: StoryProject,
  chapterIndex: number,
  currentContent: string,
  critique: string
) => {
  const chapter = project.chapters[chapterIndex];
  const charContext = project.characters.map(c => 
    `- ${c.name}: ${c.role}. Tính cách: ${c.personality}. Nỗi đau: ${c.pastPain}. Khao khát: ${c.currentDesire}.`
  ).join("\n");

  const prompt = `
    Bạn là một nhà văn đang chỉnh sửa bản thảo dựa trên góp ý của biên tập viên.

    BỐI CẢNH & NHÂN VẬT:
    ${charContext}

    NỘI DUNG GỐC (CHƯƠNG ${chapterIndex + 1}: ${chapter.title}):
    ${currentContent}

    GÓP Ý CỦA BIÊN TẬP VIÊN:
    ${critique}

    NHIỆM VỤ:
    Hãy viết lại chương này, áp dụng triệt để các góp ý trên để nâng cao chất lượng văn học. 
    Giữ nguyên cốt truyện gốc, chỉ thay đổi cách diễn đạt, miêu tả tâm lý và nhịp điệu theo hướng dẫn.
    Đảm bảo văn phong sâu lắng, giàu hình ảnh (Show, Don't Tell) theo đúng phong cách của kênh 'Nghe & Ngẫm'.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
      thinkingConfig: { thinkingBudget: 4000 }
    },
  });
  return response.text;
};

import React, { useState } from 'react';
import { StoryProject, Chapter } from '../types';
import { generateOutline, generateNextChapterOutline } from '../services/geminiService';
import { SparklesIcon, PlusIcon, TrashIcon, DragHandleIcon, LightBulbIcon } from './Icons';

interface OutlineManagerProps {
  project: StoryProject;
  onUpdate: (updated: StoryProject) => void;
}

const OutlineManager: React.FC<OutlineManagerProps> = ({ project, onUpdate }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSuggestingNext, setIsSuggestingNext] = useState(false);

  const handleGenerateOutline = async () => {
    if (project.chapters.length > 0) {
      if (!confirm("Hành động này sẽ ghi đè toàn bộ các chương hiện có. Bạn có chắc chắn không?")) return;
    }

    setIsGenerating(true);
    try {
      const outlineRaw = await generateOutline(project.title, project.premise);

      const lines = outlineRaw.split('\n').filter(l => l.trim().length > 10);
      const newChapters: Chapter[] = lines.slice(0, 12).map((line, idx) => ({
        id: Date.now().toString() + idx,
        title: line.split(':')[0]?.replace(/Chương \d+/i, '').trim() || `Phần ${idx + 1}`,
        summary: line,
        content: '',
        emotionalTone: 'Chiêm nghiệm'
      }));

      onUpdate({ ...project, chapters: newChapters });
    } catch (error) {
      alert("Lỗi khi tạo dàn ý.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSuggestNext = async () => {
    setIsSuggestingNext(true);
    try {
      const result = await generateNextChapterOutline(project);

      // Parse result using regex
      const titleMatch = result.match(/TIÊU ĐỀ:(.*)/i);
      const summaryMatch = result.match(/TÓM TẮT:(.*)/i);
      const toneMatch = result.match(/SẮC THÁI:(.*)/i);

      const newChapter: Chapter = {
        id: Date.now().toString(),
        title: titleMatch ? titleMatch[1].trim() : 'Chương mới (AI)',
        summary: summaryMatch ? summaryMatch[1].trim() : result,
        content: '',
        emotionalTone: toneMatch ? toneMatch[1].trim() : 'Bình thản'
      };

      onUpdate({ ...project, chapters: [...project.chapters, newChapter] });
    } catch (error) {
      console.error(error);
      alert("AI đang bí ý tưởng. Hãy thử lại sau.");
    } finally {
      setIsSuggestingNext(false);
    }
  };

  const addChapter = () => {
    const newChap: Chapter = {
      id: Date.now().toString(),
      title: 'Chương mới',
      summary: '',
      content: '',
      emotionalTone: 'Bình thản'
    };
    onUpdate({ ...project, chapters: [...project.chapters, newChap] });
  };

  const deleteChapter = (id: string) => {
    onUpdate({ ...project, chapters: project.chapters.filter(c => c.id !== id) });
  };

  const updateChapter = (id: string, updates: Partial<Chapter>) => {
    onUpdate({
      ...project,
      chapters: project.chapters.map(c => c.id === id ? { ...c, ...updates } : c)
    });
  };

  return (
    <div className="flex-1 overflow-y-auto p-10 bg-[#fdfaf7]">
      <header className="mb-10 max-w-4xl mx-auto flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-serif font-bold text-stone-800 mb-2">Dàn ý & Phân chương</h2>
          <p className="text-stone-500">Bản đồ cho hành trình 90 phút lắng đọng.</p>
        </div>
        <button 
          onClick={handleGenerateOutline}
          disabled={isGenerating}
          className="flex items-center gap-2 bg-stone-100 text-stone-600 px-6 py-3 rounded-full hover:bg-stone-200 disabled:opacity-50 transition-all font-bold text-sm"
        >
          <SparklesIcon className="w-4 h-4" />
          {isGenerating ? 'Đang phác thảo...' : 'Lập lại toàn bộ dàn ý'}
        </button>
      </header>

      <div className="max-w-4xl mx-auto space-y-4 pb-20">
        {project.chapters.length === 0 ? (
          <div className="bg-white rounded-3xl p-20 text-center border border-stone-100 shadow-sm">
            <p className="text-stone-400 mb-6 italic">Hãy bắt đầu bằng cách để AI hỗ trợ lập dàn ý hoặc thêm chương thủ công.</p>
            <div className="flex justify-center gap-4">
               <button 
                onClick={handleGenerateOutline}
                className="bg-amber-800 text-white px-8 py-2 rounded-full font-bold hover:bg-amber-900 shadow-lg"
              >
                Tự động tạo dàn ý
              </button>
              <button 
                onClick={addChapter}
                className="text-amber-800 border-2 border-amber-800 px-8 py-2 rounded-full font-bold hover:bg-amber-50"
              >
                + Thêm thủ công
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {project.chapters.map((chap, idx) => (
              <div key={chap.id} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex gap-6 group">
                <div className="flex flex-col items-center gap-2 text-stone-300">
                  <span className="font-serif font-bold text-2xl opacity-30">{idx + 1}</span>
                  <div className="w-px flex-1 bg-stone-100"></div>
                </div>

                <div className="flex-1 space-y-4">
                  <div className="flex justify-between items-start">
                    <input 
                      value={chap.title}
                      onChange={(e) => updateChapter(chap.id, { title: e.target.value })}
                      className="text-xl font-serif font-bold text-stone-800 bg-transparent border-none focus:outline-none focus:ring-1 focus:ring-amber-200 rounded px-1 flex-1"
                    />
                    <button onClick={() => deleteChapter(chap.id)} className="text-stone-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">
                      <TrashIcon className="w-5 h-5" />
                    </button>
                  </div>

                  <textarea 
                    value={chap.summary}
                    onChange={(e) => updateChapter(chap.id, { summary: e.target.value })}
                    className="w-full text-sm text-stone-600 bg-stone-50 rounded-xl p-4 h-24 focus:outline-none resize-none leading-relaxed"
                    placeholder="Mô tả sự kiện chính và cảm xúc cần truyền tải trong chương này..."
                  />

                  <div className="flex items-center gap-4">
                    <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Sắc thái:</span>
                    <select 
                      value={chap.emotionalTone}
                      onChange={(e) => updateChapter(chap.id, { emotionalTone: e.target.value })}
                      className="bg-amber-50 text-amber-800 text-[10px] px-3 py-1 rounded-full font-bold uppercase outline-none"
                    >
                      <option value="U sầu">U sầu</option>
                      <option value="Bình thản">Bình thản</option>
                      <option value="Chữa lành">Chữa lành</option>
                      <option value="Hoài niệm">Hoài niệm</option>
                      <option value="Kịch tính ngầm">Kịch tính ngầm</option>
                    </select>
                  </div>
                </div>
              </div>
            ))}

            <div className="grid grid-cols-2 gap-4 pt-4">
              <button 
                onClick={handleSuggestNext}
                disabled={isSuggestingNext}
                className="py-4 bg-amber-100 text-amber-800 rounded-2xl font-bold hover:bg-amber-200 transition-all flex items-center justify-center gap-3 shadow-sm disabled:opacity-50"
              >
                <LightBulbIcon className="w-6 h-6" />
                {isSuggestingNext ? 'Đang suy ngẫm...' : 'Gợi ý chương tiếp theo'}
              </button>
              <button 
                onClick={addChapter}
                className="py-4 border-2 border-dashed border-stone-200 rounded-2xl text-stone-400 font-bold hover:bg-stone-50 hover:border-stone-300 transition-all flex items-center justify-center gap-2"
              >
                <PlusIcon className="w-5 h-5" />
                Thêm chương trống
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default OutlineManager;
